@push('scripts')<script>$(function(){var t=$('#items-table'),x=$.fn.dataTable.render.text(),c=$('#item-category-filter'),u=$('#item-uom-filter'),ty=$('#item-type-filter'),a=$('#item-asset-filter'),s=$('#item-status-filter');$('.js-item-filter[data-url]').each(function(){var q=$(this);window.erpInitSelect2(q,{theme:'bootstrap-5',placeholder:q.find('option:first').text(),allowClear:true,ajax:{url:q.data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1}},processResults:function(d){return d}}});});var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.category_id=c.val();d.base_uom_id=u.val();d.item_type=ty.val();d.asset_capitalizable=a.val();d.is_active=s.val();}},buttons:[window.erpExcelButton(t)],order:[[0,'asc']],columns:[{data:'code',render:x.display},{data:'name',render:x.display},{data:'category_label',render:x.display},{data:'item_type',render:function(v,z){return z==='display'?(v==='GOODS'?'สินค้า':'บริการ'):v;}},{data:'base_uom_label',render:x.display},{data:'asset_capitalization_label',render:x.display},{data:'status_label',render:x.display},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,z,r){return z==='display'&&r.edit_url?'<a class="btn btn-sm btn-outline-dark" href="'+x.display(r.edit_url)+'"><i class="bx bx-edit me-1" aria-hidden="true"></i>แก้ไข</a>':'';}}]}));$('.js-item-filter').on('change',function(){dt.ajax.reload();});$('#item-filter-reset').on('click',function(){c.val(null).trigger('change');u.val(null).trigger('change');ty.val('');a.val('');s.val('1');dt.ajax.reload();});});</script>@endpush
